        "data": {
          "id": "gnoi-system-reboot-method",
          "kind": "enum",
          "label": "gnoi.system.RebootMethod",
          "description": "A RebootMethod determines what should be done with a target when a Reboot is\nrequested.  Only the COLD method is required to be supported by all\ntargets.  A target should return 'INVALID_ARGUMENT` if UNKNOWN or any other\nunsupported method is called.\n\nIt is vendor defined if a WARM reboot is the same as an NSF reboot.",
          "sourceSymbol": "gnoi.system.RebootMethod",
          "deprecated": false,
          "protoUrl": "https://github.com/openconfig/gnoi/blob/v0.7.0/system/system.proto#L128",
          "fields": [
            {
              "id": "unknown",
              "type": "0",
              "name": "UNKNOWN",
              "description": "Invalid default method.",
              "ref": null
            },
            {
              "id": "cold",
              "type": "1",
              "name": "COLD",
              "description": "Shutdown and restart OS and all hardware.",
              "ref": null
            },
            {
              "id": "powerdown",
              "type": "2",
              "name": "POWERDOWN",
              "description": "Halt and power down, if possible.",
              "ref": null
            },
            {
              "id": "halt",
              "type": "3",
              "name": "HALT",
              "description": "Halt, if possible.",
              "ref": null
            },
            {
              "id": "warm",
              "type": "4",
              "name": "WARM",
              "description": "Reload configuration but not underlying hardware.",
              "ref": null
            },
            {
              "id": "nsf",
              "type": "5",
              "name": "NSF",
              "description": "Non-stop-forwarding reboot, if possible.",
              "ref": null
            },
            {
              "id": "powerup",
              "type": "7",
              "name": "POWERUP",
              "description": "Apply power, no-op if power is already on.",
              "ref": null
            }
          ]
        }
