        "data": {
          "id": "gnsi-certz-v1-existing-entity",
          "kind": "message",
          "label": "gnsi.certz.v1.ExistingEntity",
          "description": "ExistingEntity is used to use artifacts provided by another SSL policy.\nThis operation will copy the entity from the provided policy and entity\ntype into the policy defined in the Rotate Request.\nIf the ssl profile doesn't exist a NotFound error will be returned.\nIf the entity type to copy is already being provided in the same\nUploadRequest then an InvalidArgument error will be returned.\n(e.g. EntityType == ENTITY_TYPE_TRUST_BUNDLE cannot be used\nif the UploadRequest contains a trust_bundle entity already)",
          "sourceSymbol": "gnsi.certz.v1.ExistingEntity",
          "deprecated": false,
          "protoUrl": "https://github.com/openconfig/gnsi/blob/v1.8.1/certz/certz.proto#L593",
          "fields": [
            {
              "id": "ssl-profile-id",
              "type": "string",
              "name": "ssl_profile_id",
              "description": "The existing SSL profile to reference.\nLeaving this field blank will result in an InvalidArgument error\nbeing returned to the client",
              "ref": null
            },
            {
              "id": "entity-type",
              "type": "EntityType",
              "name": "entity_type",
              "ref": "gnsi-certz-v1-existing-entity-entity-type"
            }
          ]
        }
