        "data": {
          "id": "gnsi-pathz-v1-get-response",
          "kind": "message",
          "label": "gnsi.pathz.v1.GetResponse",
          "description": "GetResponse returns the requested instance of the OpenConfig gNMI Path-based\nAuthorization Policy together with `version` and `created_on` information.",
          "sourceSymbol": "gnsi.pathz.v1.GetResponse",
          "deprecated": false,
          "protoUrl": "https://github.com/openconfig/gnsi/blob/v1.4.1/pathz/pathz.proto#L212",
          "fields": [
            {
              "id": "version",
              "type": "string",
              "name": "version",
              "description": "`version` contains versioning information that is controlled by\nthe policy manager and reported as-is by the telemetry reporting system\n(ie, transparent to the target policy management service). Policy managers\nshould choose version strings as discrete as possible to ease alert\ngeneration.\nAlso, this version string must be persisted by\nthe device for preservation across system reboots / cold-starts.",
              "ref": null
            },
            {
              "id": "created-on",
              "type": "uint64",
              "name": "created_on",
              "description": "`created_on` contains information when the policy was created.\nThis information is controlled by the policy manager and reported as-is\nby the telemetry reporting system (ie, transparent to the device policy\nmanagement service). Policy manager should use the timestamp of the moment\nwhen policy was created, not the time when the policy is pushed to\na particular device).\nAlso, this timestamp should be persisted by the device for preservation\nacross system reboots / cold-starts.\n`created_on` is a timestamp: the number of seconds since\nJanuary 1st, 1970 00:00:00 GMT, a.k.a. unix epoch.",
              "ref": null
            },
            {
              "id": "policy",
              "type": "AuthorizationPolicy",
              "name": "policy",
              "description": "The actual OpenConfig gNMI Path-based Authorization Policy.",
              "ref": "gnsi-pathz-authorization-policy"
            }
          ]
        }
