        "data": {
          "id": "gnsi-authz-v1-get-response",
          "kind": "message",
          "label": "gnsi.authz.v1.GetResponse",
          "description": "GetResponse returns the requested instance of the gRPC-level Authorization\nPolicy together with `version` and `created_on` information.",
          "sourceSymbol": "gnsi.authz.v1.GetResponse",
          "deprecated": false,
          "protoUrl": "https://github.com/openconfig/gnsi/blob/v1.2.4/authz/authz.proto#L244",
          "fields": [
            {
              "id": "version",
              "type": "string",
              "name": "version",
              "description": "`version` contains versioning information that is controlled by\nthe policy manager and reported as-is by the telemetry reporting system\n(ie, transparent to the target policy management service). Policy managers\nshould choose version strings as discrete as possible to ease alert\ngeneration (eg, for policies sourced from a bundle, the timestamp of\nthe bundle should be used, not the time when the policy is pushed to\na particular device). Also, this version string must be persisted by\nthe device for preservation across system reboots / cold-starts.",
              "ref": null
            },
            {
              "id": "created-on",
              "type": "uint64",
              "name": "created_on",
              "description": "`created_on` contains information when the policy was created.\nThis information is controlled by the policy manager and reported as-is\nby the telemetry reporting system (ie, transparent to the device policy\nmanagement service). Policy manager should use the timestamp of the moment\nwhen policy was created, not the time when the policy is pushed to\na particular device).\nAlso, this timestamp should be persisted by the device for preservation\nacross system reboots / cold-starts.\n`created_on` is a timestamp: the number of seconds since\nJanuary 1st, 1970 00:00:00 GMT, a.k.a. unix epoch.",
              "ref": null
            },
            {
              "id": "policy",
              "type": "string",
              "name": "policy",
              "description": "The actual gRPC-level Authorization Policy.\nIt is provided as a JSON formatted string whose structure is defined by\ngRPC.",
              "ref": null
            }
          ]
        }
